const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mapCanvas=document.getElementById('map'),mctx=mapCanvas.getContext('2d');
const types=[
{id:'inf',name:'Fuzileiros',glyph:'♟',cost:120,hp:3,range:145,damage:1,rate:1.0,speed:30,unlock:1,desc:'Esquadrão de infantaria • defesa versátil'},
{id:'apc',name:'Blindado',glyph:'▰',cost:250,hp:8,range:180,damage:2,rate:.8,speed:23,unlock:1,desc:'Veículo blindado • suporte de linha'},
{id:'tank',name:'Tanque M1',glyph:'⬟',cost:420,hp:13,range:225,damage:4,rate:1.15,speed:18,unlock:1,desc:'Carro de combate • alto poder de fogo'},
{id:'heli',name:'Resgate',glyph:'✥',cost:360,hp:6,range:145,damage:1,rate:.6,speed:35,unlock:2,desc:'Helicóptero de transporte • extração rápida'},
{id:'apache',name:'Apache',glyph:'✣',cost:540,hp:8,range:235,damage:3,rate:.48,speed:38,unlock:3,desc:'Helicóptero de ataque • suporte aéreo'},
{id:'truck',name:'Transporte',glyph:'▰',cost:300,hp:7,range:115,damage:1,rate:1.1,speed:21,unlock:2,desc:'Caminhão militar • reforço de infantaria'},
{id:'arty',name:'Artilharia',glyph:'◢',cost:620,hp:8,range:315,damage:5,rate:1.8,speed:11,unlock:4,desc:'Obuseiro autopropulsado • longo alcance'},
{id:'plane',name:'Paraquedistas',glyph:'✈',cost:750,hp:10,range:175,damage:2,rate:.7,speed:53,unlock:5,desc:'Aeronave de transporte • mobilização aérea'},
{id:'jet',name:'Caça',glyph:'➤',cost:950,hp:9,range:285,damage:6,rate:1.5,speed:64,unlock:7,desc:'Caça de superioridade aérea • ataque veloz'},
{id:'bomber',name:'Bombardeiro',glyph:'✈',cost:1250,hp:12,range:340,damage:9,rate:2.4,speed:43,unlock:9,desc:'Apoio estratégico • impacto devastador'}
];
let W=1000,H=700,scale=1,units=[],zombies=[],bullets=[],fx=[],buildings=[],money=480,kills=0,wave=1,integrity=100,selected=null,mode='select',paused=false,sound=true,last=0,spawnTimer=1.5,waveTimer=0,zombieId=0,toastTimer=0,shake=0;
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function resize(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=r.width*dpr;canvas.height=r.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);scale=r.width/1000;W=1000;H=r.height/scale;mapCanvas.width=244;mapCanvas.height=140;draw()};window.addEventListener('resize',resize);
function initBuildings(){buildings=[];const rows=[{x:0,y:0,w:95,h:65},{x:140,y:0,w:100,h:78},{x:760,y:0,w:120,h:68},{x:900,y:10,w:100,h:65},{x:0,y:130,w:90,h:90},{x:895,y:130,w:105,h:85},{x:0,y:470,w:105,h:70},{x:135,y:520,w:92,h:90},{x:775,y:500,w:104,h:90},{x:900,y:455,w:100,h:80},{x:320,y:40,w:120,h:74},{x:550,y:18,w:145,h:70},{x:315,y:520,w:115,h:88},{x:555,y:530,w:130,h:85}];for(const b of rows)buildings.push({...b,hp:100,max:100,alive:true,tone:Math.floor(rand(0,3))})}
initBuildings();
function makeUnit(type,x=rand(420,580),y=H*.55){const t=types.find(q=>q.id===type);let u={...t,id:Math.random().toString(36).slice(2),x,y,hp:t.hp,max:t.hp,tx:x,ty:y,cd:rand(0,.6),kills:0,angle:0,selected:false};units.push(u);updateRoster();return u}
makeUnit('inf',470,H*.52);makeUnit('inf',510,H*.58);makeUnit('apc',555,H*.51);
function buy(id){const t=types.find(q=>q.id===id);if(!t)return;if(wave<t.unlock){notify(`Desbloqueia na onda ${String(t.unlock).padStart(2,'0')}`);return}if(money<t.cost){notify('Suprimentos insuficientes');return}money-=t.cost;updateUI();const u=makeUnit(id,rand(430,570),H*.53+rand(-30,60));fx.push({x:u.x,y:u.y,color:'#d4ff65',r:15,life:.5,max:.5,ring:true});notify(`${t.name.toUpperCase()} mobilizado`)}
function renderShop(){const box=document.getElementById('cards');box.innerHTML='';types.forEach(t=>{const b=document.createElement('button');b.className='card'+(wave<t.unlock?' locked':'');b.disabled=wave<t.unlock||money<t.cost;b.innerHTML=`<span class="glyph">${t.glyph}</span><b>${t.name}</b><small>$ ${t.cost}</small>`;b.onclick=()=>buy(t.id);box.appendChild(b)})}
function updateUI(){document.getElementById('money').textContent='$ '+Math.floor(money).toLocaleString('pt-BR');document.getElementById('wave').innerHTML=String(wave).padStart(2,'0')+' <span style="font:500 10px DM Sans;color:#9eaa9b">/ ∞</span>';document.getElementById('kills').textContent=String(kills).padStart(3,'0');document.getElementById('integrityText').textContent=Math.ceil(integrity)+'%';document.getElementById('integrityBar').style.width=integrity+'%';document.getElementById('integrityBar').style.background=integrity<35?'#ff6958':'#d4ff65';renderShop();document.getElementById('warningText').textContent=zombies.length?`${zombies.length} INFECTADO${zombies.length>1?'S':''} NO SETOR`:'MOVIMENTO INFECTADO DETECTADO'}
function updateRoster(){const list=document.getElementById('unitList');document.getElementById('unitCount').textContent=String(units.length).padStart(2,'0')+' UNIDADES';list.innerHTML=units.length?'':`<div class="empty">Nenhuma unidade em campo</div>`;const count={};units.forEach(u=>count[u.name]=(count[u.name]||0)+1);Object.keys(count).forEach(name=>{const u=units.find(q=>q.name===name),row=document.createElement('div');row.className='unitrow';row.innerHTML=`<span class="unitglyph">${u.glyph}</span>${name}<strong>${String(count[name]).padStart(2,'0')} <span>×</span></strong>`;list.appendChild(row)})}
function notify(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
function showWave(){const el=document.getElementById('waveBanner');el.textContent=`ONDA ${String(wave).padStart(2,'0')} • HORDAS DETECTADAS`;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');notify('Nova onda detectada — prepare suas defesas');updateUI()}

function offsetY(){return (H-700)/2}function draw(){if(!ctx||!canvas.width)return;const cw=canvas.clientWidth,ch=canvas.clientHeight;ctx.clearRect(0,0,cw,ch);ctx.save();ctx.scale(scale,scale);const oy=offsetY(),cy=H/2;
// layered battlefield terrain
ctx.fillStyle='#28372b';ctx.fillRect(0,0,W,H);ctx.fillStyle='#304131';for(let y=-30;y<H;y+=64)for(let x=(Math.floor(y/64)%2)*28;x<W;x+=72){ctx.globalAlpha=.12;ctx.beginPath();ctx.ellipse(x+randSeed(x,y)*25,y+randSeed(y,x)*25,13,5,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// roads
ctx.fillStyle='#505248';ctx.fillRect(0,cy-43,W,86);ctx.fillStyle='#85816d';ctx.globalAlpha=.5;ctx.fillRect(0,cy-45,W,3);ctx.fillRect(0,cy+42,W,3);ctx.globalAlpha=.35;for(let x=0;x<W;x+=75){ctx.fillStyle='#c8ba82';ctx.fillRect(x,cy-2,38,4)}ctx.globalAlpha=1;
// road branches
ctx.fillStyle='#484a41';ctx.fillRect(468,0,64,H);ctx.globalAlpha=.25;for(let y=0;y<H;y+=75)ctx.fillRect(498,y,4,36);ctx.globalAlpha=1;
// rubble/vegetation
for(let i=0;i<34;i++){let x=(i*173+31)%W,y=(i*113+89)%Math.max(H,1);if(x>280&&x<720&&Math.abs(y-cy)<100)continue;ctx.fillStyle=i%3?'#1f3025':'#46543b';ctx.beginPath();ctx.arc(x,y,5+(i%4)*2,0,Math.PI*2);ctx.fill()}
// destructible urban blocks
for(const b of buildings){if(!b.alive)continue;const by=b.y+oy;ctx.fillStyle='#18221c';ctx.fillRect(b.x+5,by+7,b.w,b.h);const shades=['#596052','#646357','#51594d'];ctx.fillStyle=shades[b.tone];ctx.fillRect(b.x,by,b.w,b.h);ctx.fillStyle='rgba(213,198,154,.16)';ctx.fillRect(b.x+4,by+4,b.w-8,5);ctx.fillStyle='#333a32';for(let wx=b.x+12;wx<b.x+b.w-8;wx+=25)for(let wy=by+16;wy<by+b.h-7;wy+=22){ctx.fillRect(wx,wy,9,10);ctx.fillStyle='#9a8b61';ctx.fillRect(wx+2,wy+2,5,2);ctx.fillStyle='#333a32'}ctx.strokeStyle='rgba(13,20,15,.8)';ctx.lineWidth=2;ctx.strokeRect(b.x,by,b.w,b.h);if(b.hp<b.max){ctx.fillStyle='#222';ctx.fillRect(b.x,by-7,b.w,3);ctx.fillStyle='#e79557';ctx.fillRect(b.x,by-7,b.w*b.hp/b.max,3)}}
// city command center
ctx.save();ctx.translate(500,cy);ctx.fillStyle='#161e18';ctx.beginPath();ctx.arc(0,0,72,0,7);ctx.fill();ctx.strokeStyle='rgba(212,255,101,.45)';ctx.lineWidth=2;ctx.setLineDash([6,7]);ctx.beginPath();ctx.arc(0,0,64,0,7);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#56634f';ctx.fillRect(-39,-28,78,56);ctx.fillStyle='#737766';ctx.fillRect(-30,-20,60,40);ctx.fillStyle='#303c31';ctx.fillRect(-22,-13,44,26);ctx.fillStyle='#d4ff65';ctx.fillRect(-4,-24,8,7);ctx.fillRect(-3,-8,6,16);ctx.fillRect(-8,-3,16,6);ctx.fillStyle='#b9c9a0';ctx.fillRect(-6,28,12,8);ctx.restore();
// craters
for(const f of fx){if(f.crater){ctx.fillStyle='rgba(14,18,14,.62)';ctx.beginPath();ctx.ellipse(f.x,f.y,f.r,f.r*.58,0,0,7);ctx.fill();ctx.strokeStyle='rgba(161,134,91,.45)';ctx.lineWidth=2;ctx.stroke()}}
// fire lines
for(const b of bullets){ctx.strokeStyle=b.color;ctx.globalAlpha=.9;ctx.lineWidth=b.big?3:2;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-b.vx*.12,b.y-b.vy*.12);ctx.stroke();ctx.globalAlpha=1}
for(const z of zombies)drawZombie(z);
for(const u of units)drawUnit(u);
for(const f of fx){if(f.crater)continue;const a=clamp(f.life/f.max,0,1);ctx.globalAlpha=a;ctx.strokeStyle=f.color||'#ffcb67';ctx.fillStyle=f.color||'#ffcb67';if(f.ring){ctx.lineWidth=2;ctx.beginPath();ctx.arc(f.x,f.y,f.r*(1+(1-a)*.8),0,7);ctx.stroke()}else{ctx.beginPath();ctx.arc(f.x,f.y,Math.max(1,f.r*a),0,7);ctx.fill()}ctx.globalAlpha=1}
// unit command ring and selection
if(selected&&units.includes(selected)){ctx.strokeStyle='#d4ff65';ctx.lineWidth=1.5;ctx.setLineDash([4,4]);ctx.beginPath();ctx.arc(selected.x,selected.y,selected.range,0,7);ctx.stroke();ctx.setLineDash([])}
ctx.restore();drawMini();}
function randSeed(a,b){const x=Math.sin(a*12.9898+b*78.233)*43758.5453;return x-Math.floor(x)}
function drawUnit(u){ctx.save();ctx.translate(u.x,u.y);ctx.rotate(u.angle);const aerial=['heli','apache','plane','jet','bomber'].includes(u.id);if(u.selected){ctx.strokeStyle='rgba(212,255,101,.9)';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(0,0,20,13,0,0,7);ctx.stroke()}ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(0,5,aerial?17:14,7,0,0,7);ctx.fill();if(aerial){ctx.fillStyle=u.id==='heli'||u.id==='apache'?'#9ca887':'#b8bd9f';ctx.beginPath();ctx.moveTo(-14,0);ctx.lineTo(-5,-5);ctx.lineTo(9,-4);ctx.lineTo(16,0);ctx.lineTo(7,4);ctx.lineTo(-8,4);ctx.closePath();ctx.fill();ctx.strokeStyle='#252d24';ctx.lineWidth=1;ctx.stroke();if(u.id==='heli'||u.id==='apache'){ctx.strokeStyle='#d4d7b1';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-2,-9);ctx.lineTo(2,-9);ctx.moveTo(0,-9);ctx.lineTo(0,-15);ctx.moveTo(-9,-7);ctx.lineTo(8,-7);ctx.stroke()}else{ctx.fillStyle='#d4ff65';ctx.beginPath();ctx.arc(4,0,1.8,0,7);ctx.fill()}}else if(u.id==='inf'){ctx.fillStyle='#b5b999';ctx.beginPath();ctx.arc(0,-5,4,0,7);ctx.fill();ctx.fillStyle='#647158';ctx.fillRect(-3,-2,7,8);ctx.strokeStyle='#262e24';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(2,1);ctx.lineTo(9,-2);ctx.stroke()}else{ctx.fillStyle=u.id==='tank'?'#76805f':'#9a9b79';ctx.fillRect(-12,-7,23,14);ctx.fillStyle='#555e49';ctx.fillRect(-9,-9,17,3);ctx.fillStyle='#30392e';ctx.fillRect(-13,-8,4,16);ctx.fillRect(9,-8,4,16);ctx.fillStyle='#b8bc94';ctx.fillRect(-2,-3,8,6);ctx.strokeStyle='#242b23';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(4,0);ctx.lineTo(15,0);ctx.stroke()}ctx.restore();if(u.hp<u.max){ctx.fillStyle='#20281f';ctx.fillRect(u.x-12,u.y-17,24,3);ctx.fillStyle='#d4ff65';ctx.fillRect(u.x-12,u.y-17,24*u.hp/u.max,3)}}
function drawZombie(z){ctx.save();ctx.translate(z.x,z.y);ctx.rotate(z.angle);ctx.fillStyle='rgba(0,0,0,.32)';ctx.beginPath();ctx.ellipse(0,5,10,5,0,0,7);ctx.fill();ctx.fillStyle=z.elite?'#b47752':'#859875';ctx.beginPath();ctx.arc(0,-4,5,0,7);ctx.fill();ctx.fillRect(-4,-1,8,10);ctx.strokeStyle='#536147';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-3,1);ctx.lineTo(-9,6);ctx.moveTo(3,1);ctx.lineTo(9,7);ctx.moveTo(-2,9);ctx.lineTo(-5,14);ctx.moveTo(2,9);ctx.lineTo(6,14);ctx.stroke();ctx.fillStyle='#f58b68';ctx.fillRect(-2,-5,1.5,1.5);ctx.fillRect(2,-5,1.5,1.5);ctx.restore();if(z.hp<z.max){ctx.fillStyle='#172019';ctx.fillRect(z.x-9,z.y-17,18,2);ctx.fillStyle='#ff6958';ctx.fillRect(z.x-9,z.y-17,18*z.hp/z.max,2)}}
function drawMini(){if(!mctx)return;mctx.clearRect(0,0,244,140);mctx.fillStyle='#28372b';mctx.fillRect(0,0,244,140);mctx.fillStyle='#505248';mctx.fillRect(0,67,244,12);mctx.fillRect(119,0,7,140);mctx.fillStyle='#707565';for(const b of buildings)if(b.alive)mctx.fillRect(b.x/1000*244,(b.y+offsetY())/H*140,b.w/1000*244,b.h/H*140);mctx.fillStyle='#d4ff65';for(const u of units){mctx.beginPath();mctx.arc(u.x/1000*244,u.y/H*140,2,0,7);mctx.fill()}mctx.fillStyle='#ff6958';for(const z of zombies){mctx.beginPath();mctx.arc(z.x/1000*244,z.y/H*140,2,0,7);mctx.fill()}}

function spawnZombie(){const edge=Math.floor(rand(0,4));let x=edge===0?rand(0,W):edge===1?rand(0,W):edge===2?-15:W+15,y=edge===0?-15:edge===1?H+15:rand(90,H-90);const elite=wave>=4&&Math.random()<.14;const hp=(2+Math.floor(wave*.45))*(elite?2:1);zombies.push({id:++zombieId,x,y,hp,max:hp,speed:rand(15,24)+Math.min(wave,9),damage:elite?10:6,elite,angle:0,attack:rand(.2,1)})}
function nearestTarget(u){let best=null,dd=Infinity;for(const z of zombies){const d=dist(u,z);if(d<dd&&d<u.range+70){best=z;dd=d}}return best}
function fire(u,z){const d=dist(u,z),speed=u.id==='arty'||u.id==='bomber'?350:500;const damage=u.damage;bullets.push({x:u.x,y:u.y,vx:(z.x-u.x)/d*speed,vy:(z.y-u.y)/d*speed,target:z,damage,life:d/speed,color:u.id==='apache'||u.id==='jet'||u.id==='bomber'?'#ffb560':'#e3db9b',big:u.damage>=5,splash:u.id==='arty'||u.id==='bomber',from:u});u.cd=u.rate;u.angle=Math.atan2(z.y-u.y,z.x-u.x)}
function damageZombie(z,damage,from){if(!zombies.includes(z))return;z.hp-=damage;fx.push({x:z.x+rand(-4,4),y:z.y+rand(-4,4),color:'#f1956f',r:3,life:.18,max:.18});if(z.hp<=0){zombies.splice(zombies.indexOf(z),1);kills++;money+=22+(z.elite?20:0);if(from){from.kills++;if(selected===from)showSelected()}fx.push({x:z.x,y:z.y,color:'#ff715a',r:7,life:.34,max:.34});if(kills%5===0)notify('+5 infectados neutralizados • suprimentos recebidos');updateUI()}}
function tick(dt){if(paused)return;waveTimer+=dt;spawnTimer-=dt;if(spawnTimer<=0){spawnZombie();spawnTimer=Math.max(.5,2.4-wave*.11)+rand(.1,.8)}if(waveTimer>=27){wave++;waveTimer=0;spawnTimer=.6;showWave()}for(const u of units){u.cd-=dt;const target=nearestTarget(u);if(target){const d=dist(u,target);u.angle=Math.atan2(target.y-u.y,target.x-u.x);if(d<=u.range&&u.cd<=0)fire(u,target);if(d>u.range*.8&&d< u.range+60&&u.id!=='arty')moveToward(u,target.x,target.y,dt*.65)}else if(Math.hypot(u.tx-u.x,u.ty-u.y)>2)moveToward(u,u.tx,u.ty,dt)}
for(const z of [...zombies]){const goal={x:500,y:H/2},d=dist(z,goal);z.angle=Math.atan2(goal.y-z.y,goal.x-z.x);if(d<37){z.attack-=dt;if(z.attack<=0){integrity=Math.max(0,integrity-z.damage);z.attack=1.1;fx.push({x:goal.x+rand(-25,25),y:goal.y+rand(-25,25),color:'#ff6958',r:9,life:.25,max:.25});updateUI();if(integrity<=0)gameOver()}}else{z.x+=Math.cos(z.angle)*z.speed*dt;z.y+=Math.sin(z.angle)*z.speed*dt}}
for(const b of [...bullets]){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0){if(zombies.includes(b.target))damageZombie(b.target,b.damage,b.from);if(b.splash){fx.push({x:b.x,y:b.y,r:18,life:1,max:1,crater:true});for(const z of [...zombies])if(Math.hypot(z.x-b.x,z.y-b.y)<48)damageZombie(z,b.damage*.6,b.from);for(const building of buildings){if(!building.alive)continue;const cx=building.x+building.w/2,by=building.y+offsetY()+building.h/2;if(Math.hypot(cx-b.x,by-b.y)<70){building.hp-=b.damage*8;if(building.hp<=0){building.alive=false;fx.push({x:cx,y:by,r:22,life:1,max:1,crater:true});notify('Estrutura destruída!')}}}}bullets.splice(bullets.indexOf(b),1)}}for(const f of [...fx]){if(!f.crater){f.life-=dt;if(f.life<=0)fx.splice(fx.indexOf(f),1)}}if(Math.random()<dt*.55)updateUI();draw()}
function moveToward(u,x,y,dt){const d=Math.hypot(x-u.x,y-u.y);if(d<1)return;const step=Math.min(d,u.speed*dt);u.x=clamp(u.x+(x-u.x)/d*step,15,W-15);u.y=clamp(u.y+(y-u.y)/d*step,30,H-35);u.angle=Math.atan2(y-u.y,x-u.x)}
function showSelected(){const box=document.getElementById('selection');if(!selected||!units.includes(selected)){box.innerHTML='<h3>COMANDO TÁTICO</h3><p>Selecione uma unidade para ver opções e emitir ordens.</p>';return}box.innerHTML=`<h3>${selected.glyph} ${selected.name.toUpperCase()}</h3><p>${selected.desc}<br><span class="selhint">♥ ${Math.ceil(selected.hp)}/${selected.max} &nbsp; • &nbsp; ☠ ${selected.kills} neutralizados</span></p>`}
function worldPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/scale,y:(e.clientY-r.top)/scale}}
canvas.addEventListener('pointerdown',e=>{if(paused)return;const p=worldPoint(e);if(mode==='repair'){if(money<100){notify('São necessários $ 100 para reforçar');return}money-=100;integrity=Math.min(100,integrity+18);updateUI();notify('Muralha reforçada +18%');fx.push({x:500,y:H/2,color:'#d4ff65',r:45,life:.6,max:.6,ring:true});return}let hit=units.find(u=>Math.hypot(u.x-p.x,u.y-p.y)<20);if(hit){if(selected)selected.selected=false;selected=hit;hit.selected=true;showSelected();document.querySelectorAll('.tool').forEach(t=>t.classList.remove('active'));document.querySelector('[data-mode="'+mode+'"]').classList.add('active');draw();return}if(selected){selected.tx=p.x;selected.ty=p.y;selected.selected=true;if(mode==='attack'){for(const z of zombies){if(dist(z,p)<75){selected.tx=z.x;selected.ty=z.y;break}}}fx.push({x:p.x,y:p.y,color:'#d4ff65',r:8,life:.4,max:.4,ring:true});notify(mode==='attack'?'Posição de ataque definida':'Ordem de movimento enviada');}else notify('Selecione uma unidade para emitir ordens');draw()});
document.querySelectorAll('.tool[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{mode=btn.dataset.mode;document.querySelectorAll('.tool[data-mode]').forEach(b=>b.classList.toggle('active',b===btn));notify(mode==='repair'?'Toque para reforçar o setor • $ 100':mode==='attack'?'Toque para definir posição de ataque':'Toque numa unidade para selecionar')}));
document.getElementById('helpBtn').onclick=()=>document.getElementById('modal').classList.add('open');document.getElementById('closeHelp').onclick=()=>document.getElementById('modal').classList.remove('open');document.getElementById('pauseBtn').onclick=()=>{paused=!paused;document.getElementById('pauseScreen').classList.toggle('on',paused);document.getElementById('pauseBtn').textContent=paused?'▶':'Ⅱ'};document.getElementById('soundBtn').onclick=e=>{sound=!sound;e.currentTarget.textContent=sound?'♫':'♩';notify(sound?'Áudio ativo':'Áudio silenciado')};
