function spawnZombie(){const side=Math.floor(rand(0,4)),pad=14;let x,y;if(side===0){x=rand(20,W-20);y=pad}else if(side===1){x=W-pad;y=rand(20,H-20)}else if(side===2){x=rand(20,W-20);y=H-pad}else{x=pad;y=rand(20,H-20)}const elite=wave>=4&&Math.random()<Math.min(.4,.08+wave*.025),hp=(elite?5:2)+Math.floor(wave*.35);zombies.push({x,y,hp,max:hp,speed:rand(13,20)+wave*.55,damage:elite?10:5,elite,cd:0,angle:0,id:++zombieId})}
