for(const u of units){if(!units.includes(u))continue;const dx=u.tx-u.x,dy=u.ty-u.y,d=Math.hypot(dx,dy);if(d>3){const step=Math.min(d,u.speed*dt);u.x+=dx/d*step;u.y+=dy/d*step;u.angle=Math.atan2(dy,dx)}let target=null,best=Infinity;if(u.focus&&zombies.includes(u.focus)&&dist(u,u.focus)<=u.range*1.35)target=u.focus;else{u.focus=null;for(const z of zombies){const q=dist(u,z);if(q<=u.range&&q<best){best=q;target=z}}}u.cd-=dt;if(target&&u.cd<=0){u.cd=u.rate;const a=Math.atan2(target.y-u.y,target.x-u.x),speed=460;bullets.push({x:u.x,y:u.y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,damage:u.damage,target,color:u.kind==='arty'||u.kind==='bomber'?'#ffbf68':'#eff69c',big:u.damage>=5});if(u.damage>=5)fx.push({x:u.x,y:u.y,r:5,color:'#ffca69',life:.12,max:.12})}}
for(const z of zombies){if(z.dead)continue;let target=null,td=Infinity;for(const u of units){const d=dist(z,u);if(d<td&&d<38){td=d;target=u}}if(target){z.cd-=dt;if(z.cd<=0){z.cd=.85;target.hp-=z.damage;fx.push({x:target.x,y:target.y,r:6,color:'#e56555',life:.2,max:.2});if(target.hp<=0){units.splice(units.indexOf(target),1);if(selected===target)selected=null;updateRoster();notify('Unidade perdida em combate')}}}else{const dx=500-z.x,dy=H/2-z.y,d=Math.hypot(dx,dy)||1;z.angle=Math.atan2(dy,dx);z.x+=dx/d*z.speed*dt;z.y+=dy/d*z.speed*dt;if(d<57){z.cd-=dt;if(z.cd<=0){z.cd=1;integrity=Math.max(0,integrity-z.damage);fx.push({x:500+rand(-40,40),y:H/2+rand(-35,35),r:10,color:'#e56e55',life:.35,max:.35});if(integrity<=0){paused=true;showGameOver()}}}}}
for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];if(!zombies.includes(b.target)||b.target.dead){bullets.splice(i,1);continue}const dx=b.target.x-b.x,dy=b.target.y-b.y,d=Math.hypot(dx,dy),step=520*dt;if(d<step+7){damageZombie(b.target,b.damage);bullets.splice(i,1)}else{b.x+=dx/d*step;b.y+=dy/d*step;b.vx=dx/d*520;b.vy=dy/d*520}}
zombies=zombies.filter(z=>!z.dead);for(let i=fx.length-1;i>=0;i--){fx[i].life-=dt;if(fx[i].life<=0)fx.splice(i,1)}updateUI()}
function updateSelection(){const box=document.getElementById('selection');if(!selected||!units.includes(selected)){box.innerHTML='<h3>COMANDO TÁTICO</h3><p>Selecione uma unidade para ver opções e emitir ordens.</p>';return}box.innerHTML=`<h3>${selected.glyph} ${selected.name.toUpperCase()}</h3><p>Integridade ${Math.ceil(selected.hp)}/${selected.max} • ${selected.kills} eliminações<br>Alcance ${selected.range} m • ${mode==='attack'?'Toque num alvo para marcar ataque':'Toque no terreno para mover'}</p>`}
function handleCanvas(e){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/scale,y=(e.clientY-r.top)/scale;if(y>H-190&&innerWidth<750)return;let hit=null,hd=28;for(const u of units){const d=Math.hypot(u.x-x,u.y-y);if(d<hd){hit=u;hd=d}}if(mode==='repair'){if(money<100){notify('São necessários $ 100 para reforçar');return}money-=100;integrity=Math.min(100,integrity+20);notify('Setor reforçado +20%');updateUI();mode='select';document.querySelectorAll('.tool[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));updateSelection();return}if(hit&&mode==='select'){selected=hit;updateSelection();return}if(selected){selected.tx=clamp(x,20,W-20);selected.ty=clamp(y,20,H-20);selected.focus=mode==='attack'?zombies.reduce((a,z)=>dist(z,{x,y})<dist(a||{x:1e6,y:1e6},{x,y})?z:a,null):null;if(selected.focus)notify('Alvo marcado');else notify(mode==='attack'?'Posição de ataque definida':'Ordem de movimento recebida');mode='select';document.querySelectorAll('.tool[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));updateSelection()}else if(hit){selected=hit;updateSelection()}}
