function frame(now){const dt=Math.min(.05,(now-(frame.last||now))/1000);frame.last=now;update(dt);draw();requestAnimationFrame(frame)}
renderShop();updateUI();updateRoster();updateSelection();resize();showWave();requestAnimationFrame(frame);
