content.text:
.selection{width:210px;margin-left:12px;padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--panel);min-height:91px}
.selection h3{margin:0 0 4px;font:700 15px 'Barlow Condensed'}
.selection p{margin:0;color:#aab5a5;font-size:10px;line-height:1.4}
.selection .selhint{color:var(--lime)}
.overlay{position:absolute;z-index:10;inset:0;background:rgba(9,14,10,.78);backdrop-filter:blur(8px);display:none;place-items:center;padding:20px}
.overlay.open{display:grid}
.pause-indicator{position:absolute;z-index:8;inset:0;display:none;place-items:center;background:rgba(0,0,0,.4);font:800 36px 'Barlow Condensed';letter-spacing:5px}
.pause-indicator.on{display:grid}
.selection{position:absolute;right:9px;bottom:max(8px,env(safe-area-inset-bottom));width:137px;min-height:0;margin:0;padding:9px}
.selection h3{font-size:12px}
.selection p{font-size:9px}
.selection{width:128px}

