 for(const u of units){if(!units.includes(u))continue;const dx=u.tx-u.x,dy=u.ty-u.y,d=Math.hypot(dx,dy);if(d>3){const step=Math.min(d,u.speed*dt);u.x+=dx/d*step;u.y+=dy/d*step;u.angle=Math.atan2(dy,dx)}let target=null,best=Infinity;if(u.focus&&zombies.includes(u.focus)&&dist(u,u.focus)<=u.range*1.35)target=u.focus;else{u.focus=null;for(const z of zombies){const q=dist(u,z);if(q<=u.range&&q<best){best=q;target=z}}}u.cd-=dt;if(target&&u.cd<=0){u.cd=u.rate;const a=Math.atan2(target.y-u.y,target.x-u.x),speed=460;bullets.push({x:u.x,y:u.y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,damage:u.damage,target,color:u.kind==='arty'||u.kind==='bomber'?'#ffbf68':'#eff69c',big:u.damage>=5});if(u.damage>=5)fx.push({x:u.x,y:u.y,r:5,color:'#ffca69',life:.12,max:.12})}}
