 function updateSelection(){const box=document.getElementById('selection');if(!selected||!units.includes(selected)){box.innerHTML='<h3>COMANDO TÁTICO</h3><p>Selecione uma unidade para ver opções e emitir ordens.</p>';return}box.innerHTML=`<h3>${selected.glyph} ${selected.name.toUpperCase()}</h3><p>Integridade ${Math.ceil(selected.hp)}/${selected.max} • ${selected.kills} eliminações<br>Alcance ${selected.range} m • ${mode==='attack'?'Toque num alvo para marcar ataque':'Toque no terreno para mover'}</p>`}
 function handleCanvas(e){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/scale,y=(e.clientY-r.top)/scale;if(y>H-190&&innerWidth<750)return;let hit=null,hd=28;for(const u of units){const d=Math.hypot(u.x-x,u.y-y);if(d<hd){hit=u;hd=d}}if(mode==='repair'){if(money<100){notify('São necessários $ 100 para reforçar');return}money-=100;integrity=Math.min(100,integrity+20);notify('Setor reforçado +20%');updateUI();mode='select';document.querySelectorAll('.tool[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));updateSelection();return}if(hit&&mode==='select'){selected=hit;updateSelection();return}if(selected){selected.tx=clamp(x,20,W-20);selected.ty=clamp(y,20,H-20);selected.focus=mode==='attack'?zombies.reduce((a,z)=>dist(z,{x,y})<dist(a||{x:1e6,y:1e6},{x,y})?z:a,null):null;if(selected.focus)notify('Alvo marcado');else notify(mode==='attack'?'Posição de ataque definida':'Ordem de movimento recebida');mode='select';document.querySelectorAll('.tool[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));updateSelection()}else if(hit){selected=hit;updateSelection()}}
